## CI/CD Workflow

```yaml
name: CI
on:
  push:
    branches: [main]
jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm ci
      - run: npm run lint
      - run: npm test
```

![CI workflow](/images/agent-board.png)

## The Problem

AI-generated code ships fast but risks sink fast too:

- [OK]  **Security:** Hardcoded secrets, SQL injection, XSS, CSRF
- [OK]  **Type errors:** Runtime crashes that type checking would catch
- [OK]  **Performance:** N+1 queries, memory leaks, unbounded loops
- [OK]  **Dead code:** Unused imports, unreachable branches, orphaned functions
- [OK]  **Inconsistent style:** Lint failures block merge, CI fails
- [OK]  **Missing tests:** Code coverage drops, regression risk

Manual review catches some, but shipping fast means review is often rushed. Vigil automates the catch.

## What Is Vigil?

Vigil is a GitHub Actions workflow that runs automated guardrails on every PR:

```
AI generates code |    push to GitHub |    Vigil runs:
  |-- Security scan
  |-- TypeScript typecheck
  |-- ESLint linting
  |-- Unit tests
  |-- Integration tests (optional)
  ||  Code coverage check
     ||o
   All pass? |    Auto-approve for merge
   Any fail? |    Block merge, flag issues
```

## Architecture

```yaml
# .github/workflows/vigil.yml
name: Vigil - AI Code Guardrails
on: [pull_request]

jobs:
  security:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm run scan:security
      - run: npm run scan:secrets

  types:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm run typecheck

  lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm run lint

  test:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - run: npm run test -- --coverage
      - run: npm run coverage:check  # Fail if < 80%

  # All must pass for PR to merge
status-check:
  runs-on: ubuntu-latest
  needs: [security, types, lint, test]
  if: always()
  steps:
    - run: |
        if [[ "${{ needs.security.result }}" != "success" ]] || \
           [[ "${{ needs.types.result }}" != "success" ]] || \
           [[ "${{ needs.lint.result }}" != "success" ]] || \
           [[ "${{ needs.test.result }}" != "success" ]]; then
          exit 1
        fi
```

## Guardrail 1: Security Scanning

### What It Detects

| Pattern | Risk | Severity | Example |
| --- | --- | --- | --- |
| Hardcoded secrets | Critical | Critical | `const API_KEY = 'sk-1234567890'` |
| SQL injection | Critical | Critical | `db.query('SELECT * FROM users WHERE id = ' + userId)` |
| XSS vulnerability | Critical | Critical | `innerHTML = userInput` |
| Insecure random | High | High | `Math.random()` for tokens |
| Eval / exec | High | High | `eval(userCode)` |
| Insecure crypto | High | High | `md5()` instead of `argon2` |

### Implementation

```typescript
// [OK]  WRONG: Hardcoded secret
const API_KEY = 'sk-proj-1234567890';
const password = 'MyPassword123';
const dbUrl = 'postgres://admin:secret@localhost:5432/db';

// |-- a RIGHT: Use environment variables
const API_KEY = process.env.OPENAI_API_KEY;
if (!API_KEY) throw new Error('OPENAI_API_KEY not set');

const password = process.env.DATABASE_PASSWORD;
if (!password) throw new Error('DATABASE_PASSWORD not set');
```

```typescript
// [OK]  WRONG: SQL injection
const userId = req.query.id;
db.query(`SELECT * FROM users WHERE id = ${userId}`);

// |-- a RIGHT: Parameterized query
const userId = req.query.id;
db.query('SELECT * FROM users WHERE id = $1', [userId]);
```

```typescript
// [OK]  WRONG: XSS
dom.innerHTML = userInput; // Attacker injects <script>alert(1)</script>

// |-- a RIGHT: Escape or use textContent
dom.textContent = userInput;
// or
dom.innerHTML = DOMPurify.sanitize(userInput);
```

### Configure Security Scanner

```json
// .vigil/security.json
{
  "scanners": {
    "secrets": {
      "enabled": true,
      "patterns": [
        "sk-[A-Za-z0-9]{20,}",     // OpenAI key format
        "AKIA[0-9A-Z]{16}",         // AWS key format
        "-----BEGIN PRIVATE KEY-----" // Private key
      ]
    },
    "sql-injection": {
      "enabled": true,
      "patterns": ["query(`.*\${.*}`)", "query('.*\\' \\+ .*')"] // Template strings in queries
    },
    "xss": {
      "enabled": true,
      "dangerous-methods": ["innerHTML", "eval", "Function"]
    }
  }
}
```

## Guardrail 2: TypeScript Type Checking

### Why It Matters

Types catch 10-15% of bugs before runtime. AI often generates vague types or skips them entirely.

```typescript
// [OK]  WRONG: Vague types
function processUser(user) {
  return user.name.toUpperCase(); // Crashes if user is null
}

// |-- a RIGHT: Strict types
interface User {
  name: string;
  email: string;
}

function processUser(user: User | null): string {
  if (!user) throw new Error('User not provided');
  return user.name.toUpperCase();
}
```

### TypeScript Config

```json
// tsconfig.json
{
  "compilerOptions": {
    "strict": true,                    // Enable all strict checks
    "noImplicitAny": true,            // No implicit any
    "strictNullChecks": true,         // No null surprises
    "strictFunctionTypes": true,      // Function type checking
    "noImplicitThis": true,           // this context must be explicit
    "alwaysStrict": true,             // Use "use strict"
    "noUnusedLocals": true,           // Catch unused variables
    "noUnusedParameters": true,       // Catch unused params
    "noImplicitReturns": true,        // All code paths return
    "noFallthroughCasesInSwitch": true
  }
}
```

### Script

```json
// package.json
{
  "scripts": {
    "typecheck": "tsc --noEmit"
  }
}
```

## Guardrail 3: Linting

### ESLint Config

```javascript
// eslint.config.js
import js from '@eslint/js';
import tsPlugin from '@typescript-eslint/eslint-plugin';
import tsParser from '@typescript-eslint/parser';

export default [
  {
    ignores: ['dist/**', 'node_modules/**'],
  },
  {
    files: ['src/**/*.{js,ts,jsx,tsx}'],
    languageOptions: {
      parser: tsParser,
      ecmaVersion: 2020,
      sourceType: 'module',
    },
    rules: {
      ...js.configs.recommended.rules,
      ...tsPlugin.configs.recommended.rules,
      'no-console': ['warn', { allow: ['warn', 'error'] }],
      'no-unused-vars': 'off', // TS handles this
      '@typescript-eslint/no-unused-vars': ['error'],
      '@typescript-eslint/explicit-function-return-types': 'error',
      '@typescript-eslint/no-explicit-any': 'error',
      'eqeqeq': ['error', 'always'], // Use === not ==
    },
  },
];
```

### Fix Automatically

```bash
npm run lint -- --fix
# Fixes 80% of issues automatically (spacing, semicolons, quotes)
```

## Guardrail 4: Testing

### Unit Test Example

```typescript
// src/utils/auth.test.ts
import { hashPassword, verifyPassword } from './auth';

describe('Auth Utils', () => {
  it('hashes passwords consistently', async () => {
    const password = 'MySecurePassword123';
    const hash1 = await hashPassword(password);
    const hash2 = await hashPassword(password);

    // Different hashes (salted)
    expect(hash1).not.toBe(hash2);

    // But both verify
    expect(await verifyPassword(password, hash1)).toBe(true);
    expect(await verifyPassword(password, hash2)).toBe(true);
  });

  it('rejects wrong password', async () => {
    const hash = await hashPassword('correct');
    expect(await verifyPassword('wrong', hash)).toBe(false);
  });

  it('handles edge cases', async () => {
    // Empty password
    await expect(hashPassword('')).rejects.toThrow();

    // Very long password
    const longPassword = 'a'.repeat(1000);
    expect(await hashPassword(longPassword)).toBeDefined();
  });
});
```

